import{_ as t}from"./chunks/bb86b2976d876d31587d.BfM7xQ_P.js";import{_ as o}from"./chunks/f02b384d940e32141811.BV87ILES.js";import{_ as a,o as n,c as i,a6 as r}from"./chunks/framework.CnPv4DE1.js";const g=JSON.parse('{"title":"The Future Of Work Is Play (How To Create Your Own Career)","description":"","frontmatter":{"title":"The Future Of Work Is Play (How To Create Your Own Career)","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/the-future-of-work-is-play-how-to-create-your-own-career.md","filePath":"en/letters/the-future-of-work-is-play-how-to-create-your-own-career.md"}'),s={name:"en/letters/the-future-of-work-is-play-how-to-create-your-own-career.md"};function p(l,e,h,u,d,c){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="the-future-of-work-is-play-how-to-create-your-own-career" tabindex="-1">The Future Of Work Is Play (How To Create Your Own Career) <a class="header-anchor" href="#the-future-of-work-is-play-how-to-create-your-own-career" aria-label="Permalink to &quot;The Future Of Work Is Play (How To Create Your Own Career)&quot;">​</a></h1><p>Dan Koe · 2023-12-16 · <a href="https://thedankoe.com/letters/the-future-of-work-is-play-how-to-create-your-own-career/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/the-future-of-work-is-play-how-to-create-your-own-career">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/fXhmecN-AFw?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>Obsession is your key to greatness.</p><p>Expose yourself to more experience, not distraction, and let curiosity pull you down a rabbit hole of discovery.</p><p>Once you find the thing you can’t pull yourself away from, work to make it a sustainable part of your life.</p><p>This is a lesson I discovered in my childhood.</p><p>I have always been obsessed with finding a better way of living.</p><p>Everywhere I went, I paid close attention to people’s actions. Not for the sake of judgment, but discernment. I wanted to understand what actions led to a good life and which led to a bad life.</p><p>I often found myself questioning what, how, and why.</p><p>What were they pursuing?</p><p>If every action is toward a conscious or unconscious goal, it seemed like everyone was eager to be overweight, unhealthy, overworked, and broke. They didn’t have self-generated goals that shaped their decision-making.</p><p>How did that person get to where they are?</p><p>Why did they look that way?</p><p>Was it because they picked up a 1000-calorie dessert drink for breakfast with a sandwich that leaked grease from its wrapper?</p><p>Why did they go to the same job that clearly caused them immense suffering?</p><p>How did they not see the opportunity all around them? The digital world unfolding right before their eyes? A world of information and technology they can use to learn and build in record time?</p><p>Due to my questioning, I had conditioned myself to think that getting a 9-5 job was the worst outcome that could happen in my life.</p><p>It seemed like once people accepted a job offer, they were doomed to a life of comfort.</p><p>They would fill their plate with never-ending responsibilities – a mortgage, spouse, and kids – before they had the financial capability to truly dedicate their time and energy to those things. It looked like they were quick to become an adult, but were never able to reap the rewards of being one.</p><p>They chained themselves to a paycheck because they never made the choices that led to more money and time.</p><p>The danger of employment goes far beyond this.</p><p>Before we dive in, Kortex (<a href="https://kortex.co/" target="_blank" rel="noreferrer">the software</a>) is nearing completion. Kortex (<a href="https://university.kortex.co/" target="_blank" rel="noreferrer">University</a>) are the one’s who get early access along with a revolutionary curriculum for the future of work (that schools can’t teach).</p><h3 id="the-psychology-danger-of-employment" tabindex="-1">The Psychology &amp; Danger Of Employment <a class="header-anchor" href="#the-psychology-danger-of-employment" aria-label="Permalink to &quot;The Psychology &amp; Danger Of Employment&quot;">​</a></h3><p><img src="'+t+'" alt=""></p><p>I see 9-5 jobs as a stepping stone.</p><p>My problem with them is that they breed complacency and are dangerous for your psyche.</p><p>Challenge is what makes life fun and interesting.</p><p>If you halt your personal evolution by never pursuing something more, you lose purpose and fulfillment.</p><p>Entrepreneurship is the only logical option for long-term thinkers.</p><p>Entrepreneurship is the path of uncertainty.</p><p>Like slashing your way through the jungle.</p><p>You are required to learn skills that aren’t taught in schools.</p><p>You are required to be okay with failure, rejection, and slow progress.</p><p>You are required to learn from your mistakes, show up again tomorrow, and push until your strike gold.</p><p>Your psyche is wired to hunt.</p><p>The physical world has changed much faster than our mind can adapt.</p><p>We still have the same neurobiological processes as our ancestors.</p><p>If you stay in a 9-5 job for too long, you become a monkey in a cubicle.</p><p>When you get stuck in a 9-5 (or a new 9-5 like an agency or freelancing) you live in the eternal known. You can’t make new discoveries in the known.</p><p>You get bored, depressed, and see life as meaningless because the only dopamine you get is from superficial sources.</p><p>You never take risks, push into the unknown, and discover new knowledge, tools, and potentials that raise dopamine levels in the brain.</p><p>As an entrepreneur, you “hunt” for your survival by gathering knowledge, creating a valuable product, and putting it in front of people who could benefit from it.</p><p>You don’t have to hunt for your food, but you have to hunt for the resources to acquire food, like money to put toward a better future.</p><p>Aristotle condemned manual labor as harmful to the body and soul.</p><p>The Ancient Greeks saw work as a necessary part of life. But only as a means to leisure, creativity, and contemplation as they considered them the keys to happiness.</p><p>Without work, leisure loses its meaning and vice versa.</p><p>Life begins to lack balance and contrast.</p><p>Manual work isn’t always bad. But completing mindless tasks for the sake of survival or status makes you no different than a robot or animal.</p><h2 id="the-future-of-work-is-play" tabindex="-1">The Future Of Work Is Play <a class="header-anchor" href="#the-future-of-work-is-play" aria-label="Permalink to &quot;The Future Of Work Is Play&quot;">​</a></h2><blockquote><p>There are almost 7B people on this planet. Someday, I hope, there will be almost 7B companies. — Naval</p></blockquote><p><em><strong>Money is a tool for building what you want but doesn’t yet exist.</strong></em></p><p>It’s not for the material acquisition of cars and houses (although those can be achieved through a deeply spiritual vessel like business, investing, or self-development).</p><p>Technology and the internet are how you build a solution that leads to personal and collective progress.</p><p>Evolution is about solving problems with technology.</p><p>That’s what we do as humans. That is our edge. That is what sets you apart from other beings and has led to the complex world we live in filled with skyscrapers, libraries, sports, and the infinite internet.</p><p>We build, create, and solve our own problems with a plan, focus, and creativity.</p><p>Humans have the innate drive to survive the information in their genes <em>and</em> consciousness.</p><p>We have built technology since the dawn of time for the sake of life extension and youth extension.</p><p>The drive to preserve our physical bodies is natural, but it’s not for the reason that most people think.</p><p>Humans survive on the conceptual level.</p><p>We attempt to reproduce the contents of our minds.</p><p>The ideas, beliefs, and values that make us who we are.</p><p>Is a child just a physical body? When they are born, do they have a “self?” Are you creating a child just by birthing them physically? Or are you spewing your spiritual seed into their minds to create their identity?</p><p>For us to become immortal, the drive to survive our physical form and extend our youth is necessary to increase the time in which we can spread our ideas to ripple throughout consciousness and (hopefully) win the battle of good against evil. The biosphere (biology) must remain intact for the noosphere (mind) to expand and transcend to whatever is next.</p><p>In this sense, it makes sense why we do what we do.</p><p>Authors write books to become immortal and pass down their ideas to create selves around the world.</p><p>Authors and creators have had more children than Genghis Khan.</p><p>We read books and adopt ideas that align with our goals as a part of our identity.</p><p>And since most people have the goals that society assigned to them, they are perceiving and storing information that reinforces their identity. The masses are the children of society.</p><p><strong>This all points a finger at the future of work.</strong></p><p>Through evolution and technology, we have been removing labor work from our eyes.</p><p>To me, this seems like the human drive to pursue creative work further to advance the expansion and unity of mind and consciousness.</p><p>We want to do what we want, when we want, in a positive direction by pursuing our interests, solving our problems, and building solutions that create heaven on Earth.</p><p>Never has this been more of an option for the majority of the population.</p><p>We have the technology available to us to create our ideal lives with the internet.</p><h3 id="the-digital-renaissance" tabindex="-1">The Digital Renaissance <a class="header-anchor" href="#the-digital-renaissance" aria-label="Permalink to &quot;The Digital Renaissance&quot;">​</a></h3><p>The future of work, in my eyes, belongs to the creative.</p><p>The writers.</p><p>The designers.</p><p>The speakers.</p><p>The builders.</p><p>The creators.</p><p>The synthesizers.</p><p>The highest-paid individuals are and will be those who use the creative ability of their mind to solve problems that prevent progress in humanity.</p><p>This is what I teach in <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer.</a></p><p>Ideas are the building blocks of a better future.</p><p>Ideas are the primary pursuit of the creative worker.</p><p>What people don’t realize is that there is a way to achieve impossible ideas. You just need to create a path that allows you to actualize that reality.</p><p>Elon Musk wanted to land on Mars.</p><p>A few years ago, this was impossible, but it is becoming more and more possible by the day.</p><p>He didn’t start with SpaceX.</p><p>He made smart choices (among many dumb ones, you can’t skip making mistakes) to the point of having companies, capital, and a path to land on Mars.</p><p>Most people try to make the impossible possible but fail because they skipped building the ideas that must come before.</p><p>The plow came before the tractor.</p><p>The filing cabinet came before a second brain.</p><p>The horse-drawn carriage came before the car.</p><p>And most of the time, people didn’t know that the car could have existed had they not built the other solutions that made it a possibility.</p><p>In a practical sense, you have no idea what is possible for your future. And you will never find out if you don’t build a solution for the personal problems in your life.</p><p>We are going through what seems to be a second Renaissance. A digital one. An eternal one.</p><p>As we expand to new planets and the human race hits trillions in numbers, there will be thousands of Einsteins and Nietzsches.</p><p>We are back in a time where artists, thinkers, and creatives are rewarded for their risk.</p><p>This is not a time for specialists.</p><p>Nor is it a time for generalists.</p><p>We live in a time of <a href="/letters/become-a-digital-renaissance-man-and-join-the-new-rich">specialized generalism</a>.</p><p>You must laser in on a specific vision for the future and acquire the general skill and knowledge that will actualize each ascending goal that <em>creates</em> that vision.</p><p>Success is not as simple as learning one skill.</p><p>As we will find, self-education and skill acquisition – for life – in alignment with a self-generated goal is your key to sovereignty.</p><h3 id="the-new-economy" tabindex="-1">The New Economy <a class="header-anchor" href="#the-new-economy" aria-label="Permalink to &quot;The New Economy&quot;">​</a></h3><p>The Universe divides and reunites like the ocean evaporates and condenses back down into rain.</p><p>We will call this a cycle of centralization and decentralization.</p><p>Social media has caused a shift from centralized media to decentralized media.</p><p>Synthesizers – or creators – are decentralized media companies.</p><p>They compose the new public school system that is available to anyone with an internet connection.</p><p>Individuals are creating new jobs, teaching new information, and creating new paths that schools and government can’t keep up with.</p><p>Few people recognize the importance of social media as the new digital society.</p><p>Most people see it as a place to entertain themselves and use to complete a few tasks at work.</p><p>In reality, media shapes culture, society, and the economy.</p><p>Media is how we learn.</p><p>Media is how we get new information.</p><p>Media is how we communicate the value of our businesses.</p><p>Media consumes a large portion of our lives. It creates a social fabric that people rely on for civilization to operate as it does.</p><p>Social media is the collective consciousness that spreads ideas for people to adopt as a part of their identity.</p><p>Identity influences perspective. Perspective influences perception. Perception influences what we deem important or valuable to our lives.</p><p>Social media, whether you are on it or not, changes our behavior on a personal level and ripples throughout society through communication. Social media is creating new selves with the ideas hosted on it and adopted from it.</p><p>A creator can send out a message to millions of people in the blink of an eye. Imagine trying to send a message to one million people 50 years ago. It would have taken months if not much longer.</p><p>Social media changes how we spend our money because it changes what message is adopted and spread by creators.</p><p>There are the synthesizers who pursue their own goals, collect ideas to creatively achieve them, and distribute a valuable message to their readers.</p><p>Then there are the general influencers who attract the masses with looks, rather than depth, for the sake of reinforcing their ego. They may be unconsciously leading society toward a dead end.</p><p>The world needs more synthesizers.</p><p>The value creators explore unknown crevices of reality and distribute ideas that others can build with the technology available to them that leads to collective progress.</p><p>If you want to become a synthesizer, this is why I started Kortex University, <a href="https://university.kortex.co/" target="_blank" rel="noreferrer">you can apply for admissions here</a>.</p><p>With automation and AI seeing exponential growth, it only makes sense that people will get their media fix from humans.</p><p>Personal brands. Creators. Synthesizers. Same thing, different nuance and impact.</p><p>People who educate, entertain, and inspire according to their interests.</p><p>Unless we rewrite the collective psyche (which hasn’t changed much in a few hundred years) then this is inevitable. People are attracted to people, not robots.</p><p>Robots have their place in decreasing labor and increasing human creativity, though.</p><p><strong>Modern business is an extension of the self.</strong></p><p>It is a vessel for your purpose.</p><p>Your purpose evolves, and you must solve the superficial problems in your life to reach your deepest purpose.</p><p>The pattern here are the eternal markets (where the most money flows).</p><p>Health, wealth, and relationships.</p><p><a href="/letters/the-self-reliant-career-path-how-to-generate-independent-income">Solve your own problems</a> by acquiring the skill and knowledge necessary to do so through the internet.</p><p>Pass down what you learn in the form of free content and paid products.</p><p>By doing so, you not only create an independent income source, but massive social leverage.</p><p>The new economy is composed of creators that sell products which lead to progress within their community.</p><p>Some sell information. Some sell cotton clothes because they see danger in polyester as an endocrine disruptor. Some sell skin care products.</p><p>As the barrier for product creation lowers thanks to technology, we can earn a living doing what we enjoy while improving ourselves (and those in our community or readership) beyond measure.</p><h2 id="how-to-create-your-own-career" tabindex="-1">How To Create Your Own Career <a class="header-anchor" href="#how-to-create-your-own-career" aria-label="Permalink to &quot;How To Create Your Own Career&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><p>Curiosity leads to learning.</p><p>Learning leads to obsession.</p><p>Obsession leads to a life that you never thought was possible.</p><p>A life filled with enjoyment, winning, and an impact on those who see the value in the path you’ve carved out of reality.</p><p>With the – rapidly evolving – technology available to use, we no longer have to remain a puppet of society.</p><p>We can make the conscious personal choice to use the tools that have been built for us in the new economy.</p><p>We have the chance to create a career, not be assigned one.</p><p>This is the career path of the future, the direction you take is your choice within it:</p><h3 id="self-education" tabindex="-1">Self-Education <a class="header-anchor" href="#self-education" aria-label="Permalink to &quot;Self-Education&quot;">​</a></h3><p>A synthesizer is a Digital Renaissance Man.</p><p>They are constant self-educators.</p><p>They acquire the knowledge and skill to actualize their goals.</p><p>They let the goals they create, not the one’s society assigned to them, be their interest compass.</p><p>The future of work is based on creativity, not productivity.</p><p>Creativity is using your diverse knowledge that you acquire from learning skills and interests to achieve a goal.</p><p>If you have not learned anything outside of what you have been told to learn, you probably haven’t invested in your own goals, and you have a long way to go.</p><p>As discussed in <a href="/letters/you-wont-be-the-same-person-in-6-months-master-anything-fast">last weeks letter</a>, goals shape the entirety of your life, identity, and the knowledge you acquire.</p><p>This is less about becoming an expert in certain skills and interests.</p><p>This is more about having a constant influx of information to fuel what you are building to achieve your goals.</p><p>If you haven’t started yet, you must start with the foundation.</p><p>Mind, body, spirit, and business.</p><p>Educate yourself on how to solve the most burning, profitable problems in your own life and others.</p><p>If you want to make money reasonably fast, you must solve your superficial problems and help others solve theirs.</p><p>Do your part in raising the collective consciousness by helping others transcend the problems that keep them in a lower state of consciousness.</p><p>Learn, build, and sell a product around fitness, relationships, mental health, and financial freedom.</p><p>By pursuing these goals, your path will be unique. It’s obvious that nobodies path is the same. The knowledge you acquire by achieving these goals is unique to you.</p><p>Everybody’s niche is self-actualization.</p><p>Before this technological revolution, people did not self-actualize in public.</p><p>The ones building rockets are also in the self-actualization niche. They are advancing human potential.</p><p>But, you have the ability to improve yourself, earn from it, and then pursue whatever you want.</p><h3 id="code-content" tabindex="-1">Code &amp; Content <a class="header-anchor" href="#code-content" aria-label="Permalink to &quot;Code &amp; Content&quot;">​</a></h3><p>To take advantage of the future of work there are certain skills you must acquire.</p><p><strong>The Meta Skills</strong></p><p>Code and content create the internet.</p><p>They umbrella every other skill you will need to learn.</p><p>And if everything that can be done on the internet will be done on the internet, learning these is not optional.</p><p><strong>Results Oriented Skills</strong></p><p>You don’t need to learn to code, but you need technical know-how.</p><p>You need to understand the tools you can use to build a better life.</p><p>Email marketing, graphic design, video editing, website and funnel building</p><p>These are all technical tools to help you establish your foothold as a personal brand in the digital society.</p><p>“Code,” in this sense, is digital real estate.</p><p>Learn everything you can to build more digital real estate that people can find and follow.</p><p><strong>The <a href="/letters/the-1-million-dollar-skill-stack-learn-in-this-order">Evergreen Skills</a></strong></p><p>Code is the vessel for content, and content is the only way to get in front of others to attract them to your product.</p><p>Writing, speaking, marketing, and sales are the skills that provide the impactful message <em>for</em> your results oriented skills.</p><p>You can’t just write a social post and expect it to do well.</p><p>You need to understand mechanics and psychology.</p><p>Marketing and sales are applied mechanics and psychology.</p><p><strong>Personal Interests</strong></p><p>Now, you are learning the vast array of skills that are required to build a business (your digital resume) in today’s age on social media.</p><p>You’ve learned to write, speak, market, and sell through your emails, content, and web pages.</p><p>That – plus actually posting things – is how you start to build an audience.</p><p>But your personal interests are what set you apart <em>and determine what you sell.</em></p><p>Any of the above relating to business can be considered personal interests, but so can anything you’ve learned studying the mind, body, or spirit.</p><p>Your job is to use your skills to monetize the interests that make you unique.</p><h3 id="employees-entrepreneurs" tabindex="-1">Employees &amp; Entrepreneurs <a class="header-anchor" href="#employees-entrepreneurs" aria-label="Permalink to &quot;Employees &amp; Entrepreneurs&quot;">​</a></h3><p>Most people dream of being the CEO of a billion-dollar company but can’t even be the CEO of their own life.</p><p>The employee mindset is a difficult to break:</p><ul><li>You don’t pursue anything other than what you know</li><li>You don’t continue developing your skillset beyond the work that is assigned to you</li><li>You wait to be told what to do in your work and life, you don’t make the decision yourself</li></ul><p>Your parents are still your bosses even though you’ve moved out. The programming still tugs at your mind.</p><p>Entrepreneurs have a distinct set of traits that align with our ancestors and nature:</p><ul><li>They push into the unknown and create new paths</li><li>They build solutions to creative problems that advance humanity</li><li>They never stop acquiring knowledge and applying it in reality</li></ul><p>You can take either path in the new economy.</p><p>Employers hire based on your social media.</p><p>Creators hire based on your social media.</p><p>Brands hire based on your social media.</p><p>Clients hire based on your social media.</p><p>Customers buy based on your social media.</p><p>You can be an employee, but understand that entrepreneurship is an eventual step you will have to take if you want full control over your life and income.</p><h3 id="assigned-created-products" tabindex="-1">Assigned &amp; Created Products <a class="header-anchor" href="#assigned-created-products" aria-label="Permalink to &quot;Assigned &amp; Created Products&quot;">​</a></h3><p>“Everyone has a product nowadays.”</p><p>I saw this under a post by Chris Williamson promoting his new productivity drink.</p><p>The commenter said it as a negative.</p><p>As if they aren’t working for someone else who has a product.</p><p>Yes, everyone has a product nowadays. Because it is a requirement if you don’t want to be assigned a product to sell.</p><p>“I don’t want to sell, it’s sleazy.”</p><p>Then you dont understand sales. You are selling me your ideas right now to reproduce and survive your narrow identity.</p><p><em>By doing nothing, you allow people less conscious and intelligent than you to have more attention, impact, and money than you.</em></p><p><em>By doing nothing, you become a puppet to society and are assigned an unconscious life to live of selling others products and never realizing it.</em></p><p>Create a product that you would buy, use, and benefit from.</p><p>That is the only shortcut in business.</p><p>You belong to a niche, you have purchased products from that niche, and if you understand anything about business, you should skip 50% of the trial and error and sell what you’ve bought, but better.</p><h3 id="distribution-leverage" tabindex="-1">Distribution &amp; Leverage <a class="header-anchor" href="#distribution-leverage" aria-label="Permalink to &quot;Distribution &amp; Leverage&quot;">​</a></h3><blockquote><p>Build distribution, then build whatever you want. – Jack Butcher</p></blockquote><p>How to start a billion-dollar company:</p><p>Don’t.</p><p>Start as one person.</p><p>Leverage the technology available to you.</p><p>Deploy digital real estate until you have ample distribution of your products and services.</p><p>Write posts every single day that live on your profile.</p><p>Network with people to get them shared (<a href="/letters/how-to-actually-grow-on-social-media-what-they-dont-tell-you">so you can grow without the algorithm</a>).</p><p>Get on podcasts to build your authority.</p><p>Plug your newsletter so you own your audience.</p><p>Give away small free products to build your newsletter more.</p><p>Sell a low-ticket product to have more people dedicated to your brand.</p><p>With an audience of 10,000, newsletter of 1,000, and network of 100 – you can do anything you want.</p><p>You have the resources to make a full time income at this point.</p><p>Beyond that, you can funnel extra cash into building your dream company or investing.</p><p>This letter was for big picture understanding.</p><p>For practical steps, click on any of the links in this letter for previous letters of products to help.</p><p>Thank you for reading.</p><p>Dan</p><p>P.S. Kortex University gets early access to our software. Plus, the education experience is unmatched for creating your own career in the new economy. <a href="https://university.kortex.co/" target="_blank" rel="noreferrer">Apply today to be enrolled in the next cohort.</a></p>',254)])])}const w=a(s,[["render",p]]);export{g as __pageData,w as default};
